turns.script:
scene layout=caption
app pancakes height=560 | Pancakes, step by step
row pancakes | <style>
row pancakes | body{margin:0;padding:20px;font-family:var(--font);color:var(--ink);background:var(--ground);box-sizing:border-box}
row pancakes | h2{margin:0 0 4px;font-size:22px}.n{color:var(--dim);font-size:16px}
row pancakes | #t{font-size:64px;margin:12px 0;font-variant-numeric:tabular-nums}
row pancakes | p{font-size:18px;line-height:1.4;min-height:80px}
row pancakes | button{font:inherit;font-size:17px;min-height:48px;padding:0 20px;margin:4px;border:0;border-radius:var(--radius);background:var(--accent);color:var(--ground)}
row pancakes | button.q{background:transparent;color:var(--ink);border:1px solid var(--dim)}
row pancakes | #bar{height:8px;background:var(--dim);opacity:.3;border-radius:4px;overflow:hidden}#f{height:100%;background:var(--accent);width:0}
row pancakes | </style>
row pancakes | <div class="n" id="c"></div><h2 id="h"></h2><p id="d"></p>
row pancakes | <div id="bar"><div id="f"></div></div><div id="t"></div>
row pancakes | <button id="go">Start timer</button><button class="q" id="pv">Back</button><button class="q" id="nx">Next step</button>
row pancakes | <script>
row pancakes | var S=[["Mix the dry","Whisk 200 g flour, 2 tsp baking powder, 1 tbsp sugar and a pinch of salt in a big bowl.",60],
row pancakes | ["Mix the wet","Whisk 300 ml milk, 1 egg and 2 tbsp melted butter in a jug.",90],
row pancakes | ["Combine","Pour wet into dry. Stir until just mixed; small lumps are fine.",60],
row pancakes | ["Rest the batter","Leave it 5 minutes so the flour soaks and the bubbles form.",300],
row pancakes | ["Heat the pan","Medium heat, a little butter. Ready when a drop of water sizzles.",120],
row pancakes | ["First side","Pour a quarter cup per pancake. Flip when bubbles pop and edges look dry.",120],
row pancakes | ["Second side","Cook until golden underneath, then plate and keep warm.",60]];
row pancakes | var s=conduit.state()||{i:0,left:S[0][2],run:false},last=0;
row pancakes | function $(x){return document.getElementById(x)}
row pancakes | function fmt(x){x=Math.ceil(x);return Math.floor(x/60)+":"+String(x%60).padStart(2,"0")}
row pancakes | function show(){var st=S[s.i];$("c").textContent="Step "+(s.i+1)+" of "+S.length;$("h").textContent=st[0];$("d").textContent=st[1];
row pancakes | $("t").textContent=s.left<=0?"Done!":fmt(s.left);$("f").style.width=(100*(1-s.left/st[2]))+"%";$("go").textContent=s.run?"Pause":(s.left<=0?"Restart":"Start timer");}
row pancakes | function beep(){try{var a=new AudioContext(),o=a.createOscillator();o.frequency.value=880;o.connect(a.destination);o.start();o.stop(a.currentTime+.6)}catch(e){}}
row pancakes | function go(i){s.i=Math.max(0,Math.min(S.length-1,i));s.left=S[s.i][2];s.run=false;show();conduit.state(s)}
row pancakes | $("go").onclick=function(){if(s.left<=0)s.left=S[s.i][2];s.run=!s.run;show();conduit.state(s)};
row pancakes | $("nx").onclick=function(){go(s.i+1)};$("pv").onclick=function(){go(s.i-1)};
row pancakes | function tick(t){var dt=Math.min(.1,(t-last)/1000||0);last=t;if(s.run&&!document.hidden){s.left-=dt;if(s.left<=0){s.left=0;s.run=false;beep();conduit.state(s)}show()}requestAnimationFrame(tick)}
row pancakes | show();requestAnimationFrame(tick);
row pancakes | </script>
say x1 | Seven steps, each with its own timer. It beeps when a timer runs out. Makes about 8 pancakes.
